<template><section class="mini"><header><button @click="$router.push('/personal/games')">← 游戏大厅</button><h1>扫雷</h1><button @click="reset">重新开始</button></header><p>{{ message }}　💣 {{ mines }}</p><div class="mine-board"><button v-for="(c,i) in cells" :key="i" :class="{open:c.open,mine:c.open&&c.mine}" @click="open(i)" @contextmenu.prevent="flag(i)">{{ c.flag?'🚩':c.open?(c.mine?'💣':c.near||''):'' }}</button></div><small>点击翻开；电脑端右键标记地雷</small></section></template>
<script setup lang="ts">import{ref}from'vue';type C={mine:boolean,open:boolean,flag:boolean,near:number};const N=9,mines=10,cells=ref<C[]>([]),message=ref('找出所有安全格');function reset(){cells.value=Array.from({length:N*N},()=>({mine:false,open:false,flag:false,near:0}));let n=0;while(n<mines){const i=~~(Math.random()*81);if(!cells.value[i].mine){cells.value[i].mine=true;n++}}cells.value.forEach((c,i)=>c.near=around(i).filter(x=>cells.value[x].mine).length);message.value='找出所有安全格'}function around(i:number){const x=i%N,y=~~(i/N),a:number[]=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx>=0&&xx<N&&yy>=0&&yy<N&&(dx||dy))a.push(yy*N+xx)}return a}function open(i:number){const c=cells.value[i];if(c.open||c.flag||message.value.includes('结束'))return;c.open=true;if(c.mine){message.value='游戏结束';cells.value.forEach(x=>{if(x.mine)x.open=true});return}if(!c.near)around(i).forEach(open);if(cells.value.filter(x=>!x.mine).every(x=>x.open))message.value='🎉 扫雷成功！'}function flag(i:number){if(!cells.value[i].open)cells.value[i].flag=!cells.value[i].flag}reset()</script>
<style scoped>.mini{max-width:520px;margin:auto;text-align:center;padding:15px}.mini header{display:flex;align-items:center;justify-content:space-between}.mini button{border:1px solid var(--c-border);background:var(--c-bg-card);color:var(--c-text-2);border-radius:7px;padding:9px}.mine-board{display:grid;grid-template-columns:repeat(9,46px);justify-content:center;margin:22px auto}.mine-board button{height:46px;border-radius:4px;font-size:17px;font-weight:700}.mine-board .open{background:var(--c-bg-hover);color:var(--c-cyan)}.mine-board .mine{background:#ff537033}.mini small,.mini p{color:var(--c-text-2)}@media(max-width:500px){.mine-board{grid-template-columns:repeat(9,10vw)}.mine-board button{height:10vw;padding:0}.mini header{flex-wrap:wrap}.mini header h1{order:3;width:100%}}</style>
